package az.achiqyol.service.impl; import org.junit.jupiter.api.Test; import static org.assertj.core.api.Assertions.assertThat; class RatingPolicyTest { @Test void boundaries() { assertThat(RatingPolicy.color(null)).isEqualTo("GREY"); assertThat(RatingPolicy.color(1.0)).isEqualTo("RED"); assertThat(RatingPolicy.color(2.49)).isEqualTo("RED"); assertThat(RatingPolicy.color(2.5)).isEqualTo("YELLOW"); assertThat(RatingPolicy.color(3.99)).isEqualTo("YELLOW"); assertThat(RatingPolicy.color(4.0)).isEqualTo("GREEN"); } }
